    }
    // the root's unit is checked before any node's
    let unit = doc.sheet.iter().rev().find_map(|(it, _)| match it {
        syntax::SItem::Decl(d) if d.name == "unit" => Some(d),
        _ => None,
    });
    if let Some(d) = unit {
        if !sheet::unit_ok(d) {
            cx.unit_err = Some(lower::err("'unit' is px, mm, cm, m, or in", d.span));
