        let mindmaps = tree::has_mindmap(cx, &doc.stmts);
        tree::check_roots(cx, &doc.stmts, crate::diag::Span::new(0, 0))?;
        let hoisted = mindmaps && d.is_none();
        let dir = if hoisted {
