#[derive(Debug, Clone)]
pub enum Term {
    Num(f64, String, Span),
    Percent(f64, String, Span),
    Ident(String, Span),
    Str(String, Span),
    Hash(String, Span),
    Var(String, Span),
    Call(String, Vec<Expr>, Span),
    Group(Expr, Span),
    Tagged(Box<Term>, String, Span), // term ':' tag (draw segment names)
}

impl Term {
    pub fn span(&self) -> Span {
        match self {
            Term::Num(_, _, s)
            | Term::Percent(_, _, s)
            | Term::Ident(_, s)
            | Term::Str(_, s)
            | Term::Hash(_, s)
            | Term::Var(_, s)
            | Term::Call(_, _, s)
            | Term::Group(_, s)
            | Term::Tagged(_, _, s) => *s,
        }
    }
}

