// A message's label in the link layer: `.lini-sequence-message`, centred
// on its anchor, lines stacked at 1.2 em.
pub fn message_label(lb: &Label) -> String {
    let lines: Vec<&str> = lb.text.split('\n').collect();
    if lines.len() <= 1 {
        return format!(
            "      <text class=\"lini-sequence-message\" x=\"{}\" y=\"{}\" dy=\"0.358em\">{}</text>\n",
            f4(lb.x),
            f4(lb.y),
            xml_escape(&lb.text)
        );
    }
    let pitch = 1.2 * 13.0;
    let total = (lines.len() as f64 - 1.0) * pitch;
    let first = lb.y - total / 2.0 + 0.358 * 13.0;
    let mut t = String::new();
    for (k, l) in lines.iter().enumerate() {
        if k == 0 {
            t.push_str(&format!("<tspan x=\"{}\" y=\"{}\">{}</tspan>", f4(lb.x), f4(first), xml_escape(l)));
        } else {
            t.push_str(&format!("<tspan x=\"{}\" dy=\"{}\">{}</tspan>", f4(lb.x), f4(pitch), xml_escape(l)));
        }
    }
    format!("      <text class=\"lini-sequence-message\" x=\"{}\" y=\"{}\">{}</text>\n", f4(lb.x), f4(lb.y), t)
}
