                add = (need - cur) / (j - i)
                for k in range(i + 1, n):
                    xs[k] += add * min(k - i, j - i)
                tot += need - cur
            elif variant == 'shift_loop':
                add = (need - cur) / (j - i)
                for k in range(i + 1, n):
                    m = min(k - i, j - i)
                    xs[k] += add * m
                tot += add * (j - i)
