        i, j = min(a, b), max(a, b)
        need = tw(lab, 13, 400) + 16
        cur = xs[j] - xs[i]
        if cur < need:
            deficit = need - cur
            add = deficit / (j - i)
            if shift == 'A':
                for k in range(i + 1, n):
                    xs[k] += add * min(k - i, j - i)
            elif shift == 'B':
                for step in range(i + 1, j + 1):
                    for k in range(step, n):
                        xs[k] += add
            elif shift == 'C':
                for k in range(i + 1, n):
                    if k <= j:
                        xs[k] += add * (k - i)
                    else:
                        xs[k] += deficit
            elif shift == 'D':
                for k in range(i + 1, n):
                    xs[k] += add * (min(k, j) - i)
            elif shift == 'E':
                # cumulative: shift accumulates as we go
                acc = 0.0
                for k in range(i + 1, n):
