def natural(ws):
    c = 0.0
    xs = []
    for w in ws:
        c += w / 2
        xs.append(c)
        c += w / 2 + g
    return xs, c - g

def algo(ws, msgs, twf, shift, totv, fin):
    n = len(ws)
    xs, tot = natural(ws)
    for (a, b, lab) in msgs:
        i, j = min(a, b), max(a, b)
        need = twf(lab, 13, 400) + 16
        cur = xs[j] - xs[i]
        if cur < need:
            deficit = need - cur
            add = deficit / (j - i)
            if shift == 'A':
                for k in range(i + 1, n):
                    xs[k] += add * min(k - i, j - i)
            elif shift == 'B':
                for step in range(i + 1, j + 1):
                    for k in range(step, n):
                        xs[k] += add
            elif shift == 'C':
                for k in range(i + 1, n):
                    if k <= j:
                        xs[k] += add * (k - i)
                    else:
                        xs[k] += deficit
            elif shift == 'E':
                acc = 0.0
                for k in range(i + 1, n):
                    if k <= j:
                        acc += add
                    xs[k] += acc
            elif shift == 'F':
                # positions after j keep their distance to j
                for k in range(i + 1, j + 1):
                    xs[k] += add * (k - i)
                for k in range(j + 1, n):
                    xs[k] += add * (j - i)
            elif shift == 'G':
                old_j = xs[j]
                for k in range(i + 1, j + 1):
                    xs[k] = xs[i] + (xs[k] - xs[i]) + add * (k - i)
                for k in range(j + 1, n):
                    xs[k] += xs[j] - old_j
            if totv == 'a':
                tot += deficit
            elif totv == 'b':
                tot += add * (j - i)
    if totv == 'c':
        tot = xs[-1] + ws[-1] / 2
    if fin == 0:
        return [x - tot / 2 for x in xs]
    h = tot / 2
    return [x - h for x in xs]

