def v1(ws, g):  # c += w/2; x; c += w/2; c += g; tot = c - g
    c = 0.0; xs = []
    for w in ws:
        c += w / 2; xs.append(c); c += w / 2; c += g
    return xs, c - g
def v2(ws, g):  # c += w/2 + g
    c = 0.0; xs = []
    for w in ws:
        c += w / 2; xs.append(c); c += w / 2 + g
    return xs, c - g
def v3(ws, g):  # gaps only between
    c = 0.0; xs = []
    for k, w in enumerate(ws):
        if k: c += g
        c += w / 2; xs.append(c); c += w / 2
    return xs, c
def v4(ws, g):
    c = 0.0; xs = []
    for k, w in enumerate(ws):
        c += w / 2; xs.append(c); c += w / 2
        if k < len(ws) - 1: c += g
    return xs, c
def v5(ws, g):
    c = 0.0; xs = []
    for k, w in enumerate(ws):
        c += w / 2; xs.append(c); c += w / 2 + (g if k < len(ws) - 1 else 0)
    return xs, c
def v6(ws, g):
    c = 0.0; xs = []
    for k, w in enumerate(ws):
        c += w / 2; xs.append(c); c += w / 2; c += g
    tot = 0.0
    for k, w in enumerate(ws):
        tot += w
    tot += g * (len(ws) - 1)
    return xs, tot
