466	// declarations say otherwise.
467	fn note_context(ctx: &mut Ctx, i: usize) {
468	    let fs = own_value(ctx, i, "font-size").and_then(|v| value_num(&ctx.sheet.env, &v)).unwrap_or(13.0);
469	    let pad = own_value(ctx, i, "padding").and_then(|v| pad4(ctx, &v)).unwrap_or([6.0, 10.0, 6.0, 10.0]);
470	    let old = ctx.comp[i].font_size;
