473	    // descendants that inherited the old size take the new one
474	    let mut stack: Vec<usize> = ctx.nodes[i].children.clone();
475	    while let Some(c) = stack.pop() {
476	        let own = ctx.nodes[c].inline.iter().any(|d| d.name == "font-size" || d.name == "font-scale")
