        ctx.nodes[s].h = ch - sw;
    }
    let mut bottoms = vec![0.0; n];
    for k in 0..n {
        bottoms[k] = top + sizes[k].1;
    }
    for g in notes.iter_mut() {
        let i = g.node;
        ctx.nodes[i].x = g.cx;
        ctx.nodes[i].y = g.cy;
    }
    if dbg() {
        eprintln!("SEQ px={:?} sizes={:?}", px, sizes);
