def m(nloops, h, nv1, nv2):
    def note(y, nv):
        if nv == 0:
            y += 16.0; y += h
        elif nv == 1:
            t = y + 16.0; c = t + h / 2; y = c + h / 2
        elif nv == 2:
            y += 16.0 + h
        elif nv == 3:
            c = y + 16.0 + h / 2; y = c + h / 2
        elif nv == 4:
            c = (y + 16.0) + h / 2; y = c + h / 2
        elif nv == 5:
            y += 16.0; c = y + h / 2; y = c - h / 2 + h
        return y
    def walk(y0, nv):
        tops = []
        y = y0
        y += 42.0
        y = note(y, nv)
        for _ in range(nloops):
            y += 32.0; tops.append(y); y += 24.0; y += 16.0; y += 24.0
        y += 32.0
        return tops, y
    _, end = walk(0.0, nv1)
    mid = end / 2
    tops, _ = walk(-mid, nv2)
    return [repr(t + 0.5) for t in tops]

