61	// A fragment's messages belong to the diagram around it: they resolve (and
62	// auto-create their endpoints) there, after the diagram's own messages, a
63	// fragment's own messages before its nested fragments'.
64	pub fn hoist_pending(
65	    nodes: &[Node],
66	    pending: Vec<(usize, crate::ast::LinkStmt, usize)>,
67	) -> Vec<(usize, crate::ast::LinkStmt, usize)> {
68	    let frag = |i: usize| is_fragment_node(&nodes[i]);
69	    if !pending.iter().any(|p| frag(p.0)) {
70	        return pending;
71	    }
72	    let host = |mut i: usize| -> usize {
73	        while frag(i) {
74	            match nodes[i].parent {
75	                Some(p) => i = p,
76	                None => break,
77	            }
78	        }
79	        i
80	    };
81	    // fragments in pre-order
82	    let mut pre: HashMap<usize, usize> = HashMap::new();
83	    let mut stack = vec![0usize];
84	    let mut k = 0;
85	    while let Some(n) = stack.pop() {
86	        if frag(n) {
87	            pre.insert(n, k);
88	            k += 1;
89	        }
90	        for &c in nodes[n].children.iter().rev() {
91	            stack.push(c);
92	        }
93	    }
94	    let mut own = Vec::new();
95	    let mut hoisted: Vec<(usize, usize, (usize, crate::ast::LinkStmt, usize))> = Vec::new();
96	    for (pos, p) in pending.into_iter().enumerate() {
97	        if frag(p.0) {
98	            let key = pre.get(&p.0).copied().unwrap_or(usize::MAX);
99	            let h = host(p.0);
100	            hoisted.push((key, pos, (h, p.1, p.2)));
101	        } else {
102	            own.push(p);
103	        }
104	    }
105	    hoisted.sort_by_key(|e| (e.0, e.1));
106	    own.extend(hoisted.into_iter().map(|e| e.2));
