    elif nv == 1:
        t = y + 16.0; c = t + h / 2; y = c + h / 2
    elif nv == 2:
        y += 16.0 + h
    elif nv == 3:
        c = y + 16.0 + h / 2; y = c + h / 2
    elif nv == 4:
        t = y + 16.0; y = t + h
    elif nv == 5:
        y = y + (h + 16.0)
    return y

def loop_step(y, lv):
    if lv == 0:
        y += 32.0; t = y; y += 24.0; y += 16.0; y += 24.0
    elif lv == 1:
        y += 32.0; t = y; y += 64.0
    elif lv == 2:
        t = y + 32.0; y = t + 64.0
    elif lv == 3:
        y += 32.0; t = y; y = y + 24.0 + 16.0 + 24.0
    return t, y

def model(nl, n, nv1, nv2, lv1, lv2, out):
    h = HS[nl]
    y = 0.0; y += 42.0; y = note_step(y, h, nv1)
    rel = []
    for _ in range(n):
        t, y = loop_step(y, lv1); rel.append(t)
    end = y + 32.0
    mid = end / 2
    if out == 'rel':
        return [repr(t - mid + 0.5) for t in rel]
    y = -mid; y += 42.0; y = note_step(y, h, nv2)
    ab = []
    for _ in range(n):
        t, y = loop_step(y, lv2); ab.append(t)
    return [repr(t + 0.5) for t in ab]

best = []
for nv1, nv2, lv1, lv2 in itertools.product(range(6), range(6), range(4), range(4)):
    for out in ['rel', 'abs']:
        if out == 'rel' and (nv2 or lv2):
            continue
        sc = sum(model(nl, n, nv1, nv2, lv1, lv2, out) == obs[(nl, n)] for nl in [2, 3] for n in range(1, 7))
        best.append((sc, nv1, nv2, lv1, lv2, out))
best.sort(reverse=True)
print(best[:10])

